/* Local POC: real DEM terrain; fictional procurement, curated graph and answers. */
(() => {
'use strict';
const $=s=>document.querySelector(s), records=window.ORBIT_BIDS;
let active=records[0],role=2,map=null,engine=null,marker=null,ready=false,flightId=0,pendingCancel=null,question='eligibility',selectedChunk=null,terrain=true;
let category='AI·빅데이터',started=false;
let markers=[], highlighted=false, lastTelemetry=0;
let cinematic=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const escape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notice=t=>$('#message').textContent=t;
function chunks(b){return [
{id:b.id+'-C01',level:1,section:'제4조 · 참가 자격',text:'최근 3년 이내 유사 사업 단일 계약 실적 '+b.minimum+'억 원 이상과 공고에서 요구하는 등록·증빙을 갖추어야 한다.'},
{id:b.id+'-C02',level:1,section:'제6조 · 제출 기한',text:'제안서 제출 마감은 '+b.deadline+'이다. 정해진 제출서류를 기한 내 제출해야 한다.'},
{id:b.id+'-C03',level:2,section:'가상 회사 · 실적증명',text:'가상 오르빗솔루션의 유사 사업 단일 계약 실적은 '+b.companyRecord+'억 원이다. 다른 자격 요건은 별도 확인이 필요하다.'},
{id:b.id+'-C04',level:3,section:'가상 회사 · 내부 전략',text:'투찰 가격은 내부 검토 중이며 확정되지 않았다. 원가와 협력 범위는 본부 승인 후 결정한다.'}
,{id:b.id+'-C05',level:1,section:'제8조 · 평가 기준',text:'기술 평가 80점과 가격 평가 20점을 합산한다. 기술 평가에는 수행계획·보안운영·유지보수 항목이 포함된다. (가상 평가 기준)'}
].filter(c=>c.level<=role).map(c=>({...c,source:c.id.endsWith('C01')?'RFP 제4조':c.id.endsWith('C02')?'입찰공고 제6조':c.id.endsWith('C05')?'제안요청 제8조':c.level===2?'제안서 실적증명':'산출내역 내부검토'}));}
function evidence(id){const c=chunks(active).find(x=>x.id===id)||chunks(active)[0];selectedChunk=c.id;$('#source-title').textContent='['+c.source+'] '+c.section;$('#source-text').textContent=c.text;$('#source-level').textContent='L'+c.level+' / '+c.id;document.querySelectorAll('[data-chunk]').forEach(n=>n.setAttribute('aria-pressed',String(n.dataset.chunk===c.id)));}
function drawGraph(){const host=$('#graph'),w=host.clientWidth||280,h=host.clientHeight||203,cs=chunks(active);const nodes=[{id:'agency',kind:'agency',label:'발주기관',x:.2,y:.14},{id:'bid',kind:'bid',label:'선택 공고',x:.49,y:.38},{id:'site',kind:'site',label:active.city+' 위치',x:.82,y:.15},...cs.map((c,i)=>({id:c.id,kind:'chunk',label:c.source,y:i<3?.68:.94,x:.17+(i%3)*.33,chunk:c.id}))];const center=nodes[1];host.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" aria-hidden="true">'+nodes.filter(n=>n.id!=='bid').map(n=>'<line x1="'+center.x*w+'" y1="'+center.y*h+'" x2="'+n.x*w+'" y2="'+n.y*h+'" stroke="#b5a2c2" stroke-opacity=".48"/>').join('')+'</svg>'+nodes.map(n=>'<button class="node" data-kind="'+n.kind+'" '+(n.chunk?'data-chunk="'+n.chunk+'"':'')+' style="left:'+n.x*100+'%;top:'+n.y*100+'%" aria-label="'+escape(n.label)+'"><span>'+escape(n.label)+'</span></button>').join('');evidence(selectedChunk);paintLinked();}
function answer(){const cs=chunks(active);let html='',reason='';if(question==='eligibility'){$('#question').textContent='우리 회사가 실적 요건을 충족하나요?';if(role<2){html='현재 열람 가능한 문서에는 회사 실적이 없어 충족 여부를 판단할 수 없습니다.';reason='회사 자료 부족 · 답변 보류 예시';}else{html='회사 실적은 '+active.companyRecord+'억 원입니다. 따라서 <button data-evidence="'+active.id+'-C01"><mark>실적 요건을 충족합니다.</mark></button>';reason='의도적으로 삽입한 오류: 공고 요건 '+active.minimum+'억 원보다 회사 실적이 적습니다.';}}else if(question==='deadline'){$('#question').textContent='제안서 제출 기한은 언제인가요?';html='제출 마감은 <strong>'+active.deadline+'</strong>입니다.';reason='제출 일정 청크를 참조한 정상 답변 예시';}else{$('#question').textContent='내부 투찰 전략을 보여주세요.';html=role>=3?escape(cs.find(c=>c.level===3).text):'현재 허용된 자료로는 제공할 수 없습니다. 문서 관리자에게 접근 권한을 확인해 주세요.';reason=role>=3?'L3 내부 자료 시연':'권한 제한에 따른 답변 보류 시연';}$('#answer').innerHTML=html;$('#reason').textContent=reason;evidence(active.id+(question==='deadline'?'-C02':question==='strategy'&&role>=3?'-C04':'-C01'));}
function bind(){renderDirectory();if($('#source-drawer').open)$('#source-drawer').close();selectedChunk=null;highlighted=false;$('#bid-id').textContent=active.id;$('#bid-title').textContent=active.title;$('#agency').textContent=active.agency+' · '+active.month+'월 합성 공고';$('#budget').textContent=(active.budget/1e8).toFixed(1)+'억';$('#period').textContent=active.period;$('#site').textContent=active.city+' 지역 · 시연 앵커';$('#scene-city').textContent=active.english;$('#coords').textContent=active.location.lat.toFixed(4)+' N / '+active.location.lng.toFixed(4)+' E';$('#alt').textContent='로딩 대기';$('#requirements').innerHTML='<li>최근 3년 단일 실적 '+active.minimum+'억 원 이상</li><li>요구 등록·증빙 별도 확인</li><li>가상 조건 · 실제 참가 자격 아님</li>';$('#tags').innerHTML=active.tags.map(t=>'<span>'+escape(t)+'</span>').join('');document.querySelectorAll('[data-bid]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.bid===active.id)));drawGraph();answer();renderDocs();$('#infra').textContent='산단 '+active.infrastructure.park.toFixed(1)+'km · 역 '+active.infrastructure.station.toFixed(1)+'km';}
function paintLinked(){$('#graph').classList.toggle('bid-linked',highlighted);document.querySelectorAll('[data-chunk]').forEach(n=>n.classList.toggle('linked',highlighted && /-C0[15]$/.test(n.dataset.chunk)));}
function inspectGate(id){cancelFlight();active=records.find(b=>b.id===id);category=active.category;question='eligibility';bind();setAnchor();highlighted=true;paintLinked();evidence(active.id+'-C01');notice(active.city+' 게이트 → 참가 자격·평가 기준 연결을 강조했습니다.');}
function cancelFlight(){flightId++;if(pendingCancel){pendingCancel();pendingCancel=null;}if(map)map.stop();$('#state').textContent='READY';}
function leg(opts,token){return new Promise(resolve=>{let settled=false;const finish=ok=>{if(settled)return;settled=true;map.off('moveend',done);if(pendingCancel===abort)pendingCancel=null;resolve(ok);};const done=()=>finish(token===flightId),abort=()=>finish(false);pendingCancel=abort;map.once('moveend',done);map.flyTo({...opts,essential:false});});}
function viewPadding(){const left=$('.hud.left').getBoundingClientRect(),right=$('.hud.right').getBoundingClientRect();if(innerWidth<950)return {top:90,bottom:90,left:25,right:25};return {top:110,bottom:100,left:Math.min(left.right+24,innerWidth*.34),right:Math.min(innerWidth-right.left+24,innerWidth*.34)};}
async function fly(){if(!ready){notice('지도 로딩 후 다시 이동해 주세요.');return;}cancelFlight();const token=flightId,center=[active.location.lng,active.location.lat],padding=viewPadding();setAnchor();$('#state').textContent='FLYING';if(!cinematic){map.jumpTo({center,zoom:15,pitch:55,bearing:active.bearing,padding});$('#state').textContent='ANCHORED';return;}
if(!await leg({center,zoom:15,pitch:35,bearing:active.bearing,curve:1.42,speed:1.2,padding},token))return;
if(!await leg({center,zoom:15,pitch:55,bearing:active.bearing,duration:650,padding},token))return;
$('#state').textContent='ANCHORED';updateTelemetry();}

function ring(lng,lat,r){return Array.from({length:13},(_,i)=>{const a=i*Math.PI*2/12;return[lng+Math.cos(a)*r/Math.cos(lat*Math.PI/180),lat+Math.sin(a)*r];});}
function installGates(){
 const features=records.map(b=>({type:'Feature',properties:{id:b.id,color:b.color},geometry:{type:'Polygon',coordinates:[ring(b.location.lng,b.location.lat,.000045)]}}));
 map.getSource('anchor').setData({type:'FeatureCollection',features});
 markers=records.map(b=>{const el=document.createElement('button');el.type='button';el.className='gate '+b.gate;el.style.setProperty('--gate',b.color);el.setAttribute('aria-label',b.city+' 공고 근거 보기');el.innerHTML='<span class="gate-art"><i class="pulse"></i><i class="pulse second"></i><i class="pulse third"></i><i class="shaft"></i><i class="core"></i></span><span class="gate-label">'+escape(b.city)+' <small>DEMO / 0'+(records.indexOf(b)+1)+'</small></span>';el.addEventListener('click',e=>{e.stopPropagation();inspectGate(b.id);});const m=new engine.Marker({element:el,anchor:'bottom'}).setLngLat([b.location.lng,b.location.lat]).addTo(map);return {id:b.id,el,m};});
 setAnchor();
}
function setAnchor(){if(!ready)return;markers.forEach(m=>m.el.classList.toggle('selected',m.id===active.id));document.documentElement.style.setProperty('--active-gate',active.color);}
function updateTelemetry(){if(!map||document.body.classList.contains('virtual-mode'))return;const now=performance.now();if(map.isMoving()&&now-lastTelemetry<180)return;lastTelemetry=now;const center=map.getCenter();$('#coords').textContent=center.lat.toFixed(4)+' N / '+center.lng.toFixed(4)+' E';$('#camera').textContent=map.getPitch().toFixed(1)+'° / '+map.getBearing().toFixed(1)+'°';if(ready&&terrain){const z=map.queryTerrainElevation([active.location.lng,active.location.lat]);$('#alt').textContent=Number.isFinite(z)?'약 '+Math.round(z)+' m':'타일 로딩 / 값 미확인';}else $('#alt').textContent=terrain?'로딩 대기':'지형 OFF';}
async function init(){try{engine=await import('https://unpkg.com/maplibre-gl@6.9.0/dist/maplibre-gl.mjs');engine.setMaxParallelImageRequests(8);const style=await window.makeRealityStyle();
map=new engine.Map({container:'map',style,center:[127.6,35.9],zoom:4.5,pitch:0,bearing:-15,maxPitch:70,maxZoom:16,fadeDuration:0,pixelRatio:Math.min(devicePixelRatio,1.25),maxTileCacheSize:240,canvasContextAttributes:{antialias:false}});
map.on('load',()=>{map.setProjection({type:'globe'});map.scrollZoom.setWheelZoomRate(1/260);map.scrollZoom.setZoomRate(1/80);map.dragPan.enable({linearity:.2,deceleration:5000,maxSpeed:1200});window.paintReality(map,'night');$('#map-light').textContent='야간 · NIGHT';map.addSource('anchor',{type:'geojson',data:{type:'FeatureCollection',features:[]}});try{map.addLayer(window.createHologramLayer(engine,records));}catch(e){console.error(e);notice('홀로그램 셰이더 로딩 실패 · 위치 마커로 탐색할 수 있습니다.');}ready=true;$('#fly').disabled=false;installGates();notice('8개 가상 공고 · 게이트를 누르면 참가 자격·평가 기준이 연결됩니다. 지형 강조 1.6× / 건물 데이터 범위는 지역별로 다릅니다.');$('#state').textContent='READY';updateTelemetry();});
map.on('movestart',()=>document.body.classList.add('moving'));map.on('moveend',()=>document.body.classList.remove('moving'));

map.on('zoom',()=>document.body.classList.toggle('orbital-view',map.getZoom()<6));document.body.classList.add('orbital-view');map.on('move',updateTelemetry);map.on('idle',updateTelemetry);map.on('dragstart',()=>cancelFlight());map.on('zoomstart',e=>{if(e.originalEvent)cancelFlight();});map.on('error',e=>{notice('지도/고도 자료 일부를 불러오지 못했습니다. 인터넷 연결 또는 공급자 응답을 확인하세요. 상세: '+String(e.error?.message||'지도 로딩 오류').slice(0,110));});}catch(e){notice('3D 엔진을 열지 못했습니다. 인터넷 연결과 WebGL 지원을 확인하세요. 문서·그래프 시연은 계속 사용할 수 있습니다.');$('#state').textContent='MAP UNAVAILABLE';console.error(e);}}

function renderDirectory(){$('#categories').innerHTML=window.ASTRA_CATEGORIES.map(c=>'<button data-category="'+c+'" aria-pressed="'+(c===category)+'">'+c+'</button>').join('');$('#bid-list').innerHTML=records.filter(b=>b.category===category).map(b=>'<button data-bid="'+b.id+'" class="bid-card" aria-pressed="'+(b.id===active.id)+'"><small>'+escape(b.city)+' / '+b.id+'</small><strong>'+escape(b.title)+'</strong><span>'+(b.budget/1e8).toFixed(1)+'억 · '+b.period+'</span></button>').join('');}
function renderDocs(){$('#right-spec').textContent=active.title+' · '+(active.budget/1e8).toFixed(1)+'억 / '+active.period;$('#doc-pipeline').innerHTML='<p class="fine">문서 수집 → 청크 → 검색 → 답변 대조 · 합성 자료</p><div class="doc-tags">'+window.ASTRA_DOCS.map((d,i)=>'<button data-document="'+i+'">'+escape(d)+'</button>').join('')+'</div>';}
let returnFocus=null;
function openSource(id,docIndex){const c=chunks(active).find(c=>c.id===id)||chunks(active)[0],drawer=$('#source-drawer');if(!drawer.open)returnFocus=document.activeElement;const source=docIndex===undefined?c.source:window.ASTRA_DOCS[docIndex];$('#drawer-title').textContent=source;$('#drawer-meta').textContent=active.title+' / '+active.id+' · 가상 원문';$('#drawer-body').innerHTML='<p>다음은 데모를 위한 합성 문서입니다.</p><h3>'+escape(c.section)+'</h3><p><mark>'+escape(docIndex===undefined?c.text:active.documents[docIndex])+'</mark></p><p>사업별 제출 조건은 해당 공고와 첨부 문서를 함께 확인합니다.</p>';if(!drawer.open)drawer.showModal();}
function setupAccess(){const enter=admin=>{role=admin?3:1;$('#role').value=String(role);document.body.classList.remove('locked');$('#workspace').inert=false;$('#login-screen').hidden=true;bind();if(!started){started=true;init();}else map?.resize();$('#search').focus();};$('#login-card').addEventListener('submit',e=>{e.preventDefault();enter(false);});$('#ops-direct').addEventListener('click',()=>enter(true));$('#logout').addEventListener('click',()=>{cancelFlight();$('#workspace').inert=true;$('#login-screen').hidden=false;document.body.classList.add('locked');$('#operator').value='';$('#operator').focus();});$('#drawer-close').addEventListener('click',()=>$('#source-drawer').close());$('#source-drawer').addEventListener('close',()=>returnFocus?.focus());document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.category){category=b.dataset.category;renderDirectory();}if(b.dataset.document!==undefined)openSource(active.id+'-C01',Number(b.dataset.document));});}
$('#search-form').addEventListener('submit',e=>{e.preventDefault();const term=$('#search').value.trim().toLowerCase();const matches=term?records.filter(b=>[b.city,b.title,b.agency,b.id].some(v=>v.toLowerCase().includes(term))):records;$('#search-results').hidden=false;$('#search-results').innerHTML=matches.length?matches.map(b=>'<button data-result="'+b.id+'">'+escape(b.city+' · '+b.title)+'</button>').join(''):'일치하는 가상 공고가 없습니다. 지역명 또는 가상 발주기관명을 입력하세요.';if(matches.length===1)select(matches[0].id);});
function select(id){cancelFlight();active=records.find(b=>b.id===id);category=active.category;question='eligibility';bind();if(ready){setAnchor();fly();}$('#search-results').hidden=true;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.bid||b.dataset.result)select(b.dataset.bid||b.dataset.result);if(b.dataset.chunk){evidence(b.dataset.chunk);openSource(b.dataset.chunk);fly();}if(b.dataset.kind==='site')fly();if(b.dataset.kind==='agency')notice(active.agency+'는 가상 발주기관입니다. 지도의 좌표는 기관 주소가 아닌 시연 지역 대표점입니다.');if(b.dataset.kind==='bid')fly();if(b.dataset.question){question=b.dataset.question;answer();if(question==='eligibility')openSource(active.id+'-C01');}if(b.dataset.evidence){evidence(b.dataset.evidence);openSource(b.dataset.evidence);}});
$('#map-light').addEventListener('click',()=>{if(!ready)return;const next=document.body.dataset.mapLight==='night'?'dusk':'night';window.paintReality(map,next);$('#map-light').textContent=next==='night'?'야간 · NIGHT':'황혼 · DUSK';});
$('#role').addEventListener('change',e=>{role=Number(e.target.value);selectedChunk=null;drawGraph();answer();});$('#fly').addEventListener('click',fly);$('#cancel').addEventListener('click',cancelFlight);$('#overview').addEventListener('click',()=>{if(!ready)return;cancelFlight();map.flyTo({center:[127.5,36.2],zoom:4.5,pitch:0,bearing:0,padding:viewPadding(),curve:1.42,speed:1.2,...(!cinematic?{duration:0}:{})});});$('#terrain-toggle').addEventListener('click',()=>{if(!ready)return;terrain=!terrain;map.setTerrain(terrain?{source:'dem',exaggeration:1.6}:null);$('#terrain-toggle').textContent='3D 지형 '+(terrain?'ON':'OFF');$('#terrain-toggle').setAttribute('aria-pressed',String(terrain));updateTelemetry();});$('#motion').textContent='카메라 연출 '+(cinematic?'ON':'OFF');$('#motion').setAttribute('aria-pressed',String(cinematic));$('#motion').addEventListener('click',()=>{cinematic=!cinematic;cancelFlight();$('#motion').textContent='카메라 연출 '+(cinematic?'ON':'OFF');$('#motion').setAttribute('aria-pressed',String(cinematic));});document.addEventListener('visibilitychange',()=>document.body.classList.toggle('paused',document.hidden));new ResizeObserver(drawGraph).observe($('#graph'));$('.places').innerHTML=records.map(b=>'<button data-bid="'+b.id+'" style="--gate:'+b.color+'">'+escape(b.city)+'</button>').join('');window.realityMode=on=>{cancelFlight();if(on){map?.resize();updateTelemetry();}};$('#fly').disabled=true;bind();setupAccess();
})();
